#include <metal_stdlib>
using namespace metal;
struct V { float4 position [[position]]; float2 uv; };
vertex V macws_nv12_v(uint n [[vertex_id]]) {
  const float2 p[3] = {float2(-1,-1), float2(3,-1), float2(-1,3)};
  V o; o.position=float4(p[n],0,1); o.uv=float2((p[n].x+1)*0.5,1-(p[n].y+1)*0.5); return o;
}
fragment float4 macws_nv12_f(V i [[stage_in]], texture2d<float> yt [[texture(0)]], texture2d<float> uvt [[texture(1)]]) {
  constexpr sampler s(coord::normalized, address::clamp_to_edge, filter::nearest);
  float yc=yt.sample(s,i.uv).r; float2 uvc=uvt.sample(s,i.uv).rg;
  float y=max(0.0,(yc-16.0/255.0)*(255.0/219.0)); float u=(uvc.x-128.0/255.0)*(255.0/224.0); float v=(uvc.y-128.0/255.0)*(255.0/224.0);
  float3 rgb=float3(y+1.5748*v, y-0.1873*u-0.4681*v, y+1.8556*u);
  return float4(clamp(rgb,0.0,1.0),1.0);
}
